Refactor this code by extracting the tax computation buried inside the loop:

def invoice(lines, region):
    result = []
    for line in lines:
        base = line['qty'] * line['price']
        if region == 'EU':
            tax = base * 0.2
        elif region == 'US-CA':
            tax = base * 0.0725
        elif region == 'US-NY':
            tax = base * 0.04
        else:
            tax = 0
        result.append({'desc': line['desc'], 'net': base, 'tax': round(tax, 2), 'gross': round(base + tax, 2)})
    return result

output:
TAX_RATES = {'EU': 0.2, 'US-CA': 0.0725, 'US-NY': 0.04}

def tax_for(base, region):
    return base * TAX_RATES.get(region, 0)

def invoice(lines, region):
    result = []
    for line in lines:
        base = line['qty'] * line['price']
        tax = tax_for(base, region)
        result.append({'desc': line['desc'], 'net': base, 'tax': round(tax, 2), 'gross': round(base + tax, 2)})
    return result

What changed: tax policy moved out of the loop into tax_for plus a rate table, so adding a region no longer touches the invoice code.

