Refactor this code by extracting the three phases into named functions:

def run(path):
    raw = []
    with open(path) as f:
        for line in f:
            line = line.strip()
            if line and not line.startswith('#'):
                raw.append(line)
    cleaned = []
    for r in raw:
        r = r.lower()
        r = ''.join(ch for ch in r if ch.isalnum() or ch == ' ')
        cleaned.append(' '.join(r.split()))
    stats = {}
    for c in cleaned:
        for word in c.split():
            stats[word] = stats.get(word, 0) + 1
    return stats

output:
def read_lines(path):
    with open(path) as f:
        return [l.strip() for l in f if l.strip() and not l.startswith('#')]

def normalize(text):
    text = ''.join(ch for ch in text.lower() if ch.isalnum() or ch == ' ')
    return ' '.join(text.split())

def word_counts(lines):
    stats = {}
    for word in ' '.join(lines).split():
        stats[word] = stats.get(word, 0) + 1
    return stats

def run(path):
    return word_counts([normalize(l) for l in read_lines(path)])

What changed: the monolithic run() became a pipeline of read_lines, normalize and word_counts; each phase is independently testable and reusable.

def header():
    return ['SALES REPORT', '=' * 40]

def body(rows):
    return [f"{r['name']:<20} {r['amount']:>10.2f}" for r in rows]

def footer(rows):
    total = sum(r['amount'] for r in rows)
    return ['-' * 40, f"{'TOTAL':<20} {total:>10.2f}", f'Generated at {datetime.now()}']

def report(rows):
    return '\n'.join(header() + body(rows) + footer(rows))

What changed: header, body and footer are separate functions; total is computed in footer instead of being threaded through the loop.

