def fetch_user(uid):
    for attempt in range(3):
        try:
            return api.get(f'/users/{uid}')
        except TimeoutError:
            time.sleep(0.5)
    raise RuntimeError('user fetch failed')

def fetch_orders(uid):
    for attempt in range(3):
        try:
            return api.get(f'/users/{uid}/orders')
        except TimeoutError:
            time.sleep(0.5)
    raise RuntimeError('orders fetch failed')

output:
def with_retry(fn, attempts=3, delay=0.5):
    for attempt in range(attempts):
        try:
            return fn()
        except TimeoutError:
            if attempt == attempts - 1:
                raise
            time.sleep(delay)

def fetch_user(uid):
    return with_retry(lambda: api.get(f'/users/{uid}'))

def fetch_orders(uid):
    return with_retry(lambda: api.get(f'/users/{uid}/orders'))

What changed: retry mechanics live in one with_retry helper; the two fetchers now only describe their own request.

