@app.post('/events')
def handle(payload):
    event = json.loads(payload['body'])
    if event.get('type') not in ('click', 'view', 'purchase'):
        return '', 204
    event['ts'] = int(time.time())
    event['session'] = event.get('session', 'anon')
    db.events.insert(event)
    if event['type'] == 'purchase':
        revenue.observe(event['amount'])
    return '', 202

output:
ALLOWED = {'click', 'view', 'purchase'}

def parse_event(payload):
    event = json.loads(payload['body'])
    if event.get('type') not in ALLOWED:
        return None
    event['ts'] = int(time.time())
    event['session'] = event.get('session', 'anon')
    return event

def record(event):
    db.events.insert(event)
    if event['type'] == 'purchase':
        revenue.observe(event['amount'])

@app.post('/events')
def handle(payload):
    event = parse_event(payload)
    if event is None:
        return '', 204
    record(event)
    return '', 202

What changed: parsing/normalization and recording were extracted, leaving the handler as pure routing glue.

instruction:
Refactor this code by extracting the collision checks into helper functions:

def step(player, boxes, walls):
    x, y = player['x'], player['y']
    if (x, y) in walls:
        return
    for b in boxes:
        if abs(b['x'] - x) <= 1 and abs(b['y'] - y) <= 1:
            if b['movable']:
                b['x'] += x - player['x']
                b['y'] += y - player['y']
            else:
                return
    player['x'], player['y'] = x, y

output:
def hits_wall(x, y, walls):
    return (x, y) in walls

def touching_box(x, y, boxes):
    return next((b for b in boxes if abs(b['x'] - x) <= 1 and abs(b['y'] - y) <= 1), None)

def step(player, boxes, walls):
    nx, ny = player['x'], player['y']
    if hits_wall(nx, ny, walls):
        return
    box = touching_box(nx, ny, boxes)
    if box is not None:
        if not box['movable']:
            return
        box['x'] += nx - player['x']
        box['y'] += ny - player['y']
    player['x'], player['y'] = nx, ny

What changed: wall and box detection became predicates, and the step function now reads as a sequence of rules instead of nested conditionals.

