def signup(pw, confirm):
    if len(pw) < 8:
        return 'too short'
    if not any(c.isdigit() for c in pw):
        return 'needs a digit'
    if not any(c.isupper() for c in pw):
        return 'needs an uppercase letter'
    if pw != confirm:
        return 'passwords do not match'
    return None

output:
def password_policy(pw):
    if len(pw) < 8:
        return 'too short'
    if not any(c.isdigit() for c in pw):
        return 'needs a digit'
    if not any(c.isupper() for c in pw):
        return 'needs an uppercase letter'
    return None

def signup(pw, confirm):
    error = password_policy(pw)
    if error:
        return error
    if pw != confirm:
        return 'passwords do not match'
    return None

What changed: policy rules are reusable for reset/change flows, and signup only orchestrates policy plus confirmation.

