def to_usd(rows, rates):
    out = []
    for r in rows:
        if r['ccy'] == 'EUR':
            amount = r['amount'] * rates['EUR']
        elif r['ccy'] == 'GBP':
            amount = r['amount'] * rates['GBP']
        elif r['ccy'] == 'USD':
            amount = r['amount']
        else:
            amount = None
        out.append({**r, 'usd': amount})
    return out

output:
def convert(amount, ccy, rates):
    if ccy == 'USD':
        return amount
    rate = rates.get(ccy)
    return None if rate is None else amount * rate

def to_usd(rows, rates):
    return [{**r, 'usd': convert(r['amount'], r['ccy'], rates)} for r in rows]

What changed: conversion rules are isolated in convert(); the loop now only maps rows, and unknown currencies are handled in one place.

