def main():
    with open('data.csv') as f:
        rows = []
        for i, line in enumerate(f):
            line = line.strip()
            if i == 0:
                continue
            cells = [c.strip() for c in line.split(',')]
            if len(cells) < 4:
                continue
            rows.append({'name': cells[0], 'city': cells[1], 'qty': int(cells[2]), 'price': float(cells[3])})
    print(len(rows))

output:
HEADER_COLS = 4

def parse_row(line, skip_header=False):
    if skip_header:
        return None
    cells = [c.strip() for c in line.strip().split(',')]
    if len(cells) < HEADER_COLS:
        return None
    return {'name': cells[0], 'city': cells[1], 'qty': int(cells[2]), 'price': float(cells[3])}

def main():
    with open('data.csv') as f:
        lines = list(f)
    rows = [r for i, line in enumerate(lines) if (r := parse_row(line, skip_header=i == 0))]
    print(len(rows))

What changed: parsing moved into parse_row with explicit skip/None semantics, so main() no longer mixes file iteration with field logic.

def humanize_duration(seconds):
    h, rem = divmod(int(seconds), 3600)
    m, s = divmod(rem, 60)
    return f'{h}h {m}m {s}s'

def done(start):
    print(f'finished in {humanize_duration(time.time() - start)}')

def checkpoint(start, label):
    print(f'{label} after {humanize_duration(time.time() - start)}')

What changed: elapsed-time formatting was extracted once; both log calls pass their message shape and reuse the helper.

